Method.Source:
/// <summary>
/// Generates pricing rule copy from a pre-defined pricing attribute group; the condition value is defaulted by default value of <c>IPricingAttribute</c>.
/// </summary>
/// <param name = "_priceAttrGroup">The price attribute group.</param>
/// <returns>Generated pricing rule copy.</returns>
internal GUPPricingRuleCopy initPricingRuleCopy(GUPPricingAttributeGroup _priceAttrGroup)
{

    ttsbegin;

    this.selectForUpdate(true);
    this.clearRuleConditions();
    this.PriceAttributeGroupName = _priceAttrGroup.Name;
    switch (this.getSourceLevel())
    {
        case GUPPricingAttributeSourceLevel::Header:
            this.ExclusionType = GUPPricingRuleExclusionType::Customer;
            break;
        case GUPPricingAttributeSourceLevel::Line:
            if (this.ExclusionType != GUPPricingRuleExclusionType::ProductVariant)
            {
                this.ExclusionType = GUPPricingRuleExclusionType::Product;
            }
            break;
    }
    this.update();

    GUPPricingRuleConditionCopy ruleConditionCopy;
    GUPPricingAttributeLink attrLink;
    ruleConditionCopy.selectForUpdate(true);
    while select attrLink where attrLink.PriceAttributeGroupName == _priceAttrGroup.Name
    {
        ruleConditionCopy.clear();
        ruleConditionCopy.RuleId = this.RuleId;
        ruleConditionCopy.ConditionAttribute = attrLink.RecId;
        ruleConditionCopy.ConditionValue = attrLink.DefaultValue;
        ruleConditionCopy.insert();
    }

    ttscommit;

    return this;
}

/// <summary>
/// Initializes pricing rule copy with existing pricing rule
/// </summary>
/// <param name = "_pricingRule">The base pricing rule.</param>
internal void initFromPricingRule(GUPPricingRule _pricingRule)
{
    ttsbegin;
    GUPPricingRuleCopy pricingRuleCopy;
    delete_from pricingRuleCopy where pricingRuleCopy.RuleId == _pricingRule.RecId;

    this.selectForUpdate(true);
    this.ExclusionType = _pricingRule.ExclusionType;
    this.PriceAttributeGroupName = _pricingRule.PriceAttributeGroupName;
    this.RuleId = _pricingRule.RecId;
    this.AllowMultiValue = _pricingRule.AllowMultiValue;
    this.insert();

    GUPPricingRuleCondition pricingRuleCondition;
    GUPPricingRuleConditionCopy pricingRuleConditionCopy;
    delete_from pricingRuleConditionCopy where pricingRuleConditionCopy.RuleId == this.RuleId;
    while select pricingRuleCondition
        where pricingRuleCondition.RuleId == this.RuleId
    {
        pricingRuleConditionCopy.clear();
        pricingRuleConditionCopy.ConditionAttribute = pricingRuleCondition.ConditionAttribute;
        pricingRuleConditionCopy.ConditionValue = pricingRuleCondition.ConditionValue;
        pricingRuleConditionCopy.RuleId = this.RuleId;
        pricingRuleConditionCopy.insert();
    }

    GUPPricingRuleExclusion pricingRuleExclusion;
    GUPPricingRuleExclusionCopy pricingRuleExclusionCopy;
    delete_from pricingRuleExclusionCopy where pricingRuleExclusionCopy.RuleId == this.RuleId;
    while select pricingRuleExclusion
        where pricingRuleExclusion.RuleId == this.RuleId
    {
        this.addToExclusion(pricingRuleExclusion.Exclusion);
    }

    ttscommit;
}

/// <summary>
/// Copies current copy table data into base pricing rule.
/// </summary>
internal void CopyToPricingRule()
{
    if (!this.RuleId)
    {
        return;
    }

    ttsbegin;

    GUPPricingRule pricingRule;
    select firstonly pricingRule where pricingRule.RecId == this.RuleId;
    pricingRule.selectForUpdate(true);
    pricingRule.ExclusionType = this.ExclusionType;
    pricingRule.PriceAttributeGroupName = this.PriceAttributeGroupName;
    pricingRule.AllowMultiValue = this.AllowMultiValue;
    pricingRule.update();
    if (this.PriceAttributeGroupName == '')
    {
        GUPPricingAttributeLineState::clearLineState(tableNum(GUPPricingRule), this.RuleId);
    }

    GUPPricingRuleCondition ruleCondition;
    GUPPricingRuleExclusion ruleExclusion;
    delete_from ruleCondition where ruleCondition.RuleId == this.RuleId;
    delete_from ruleExclusion where ruleExclusion.RuleId == this.RuleId;

    GUPPricingRuleConditionCopy ruleConditionCopy;
    while select ruleConditionCopy
            where ruleConditionCopy.RuleId == this.RuleId
    {
        ruleCondition.clear();
        ruleCondition.ConditionAttribute = ruleConditionCopy.ConditionAttribute;
        ruleCondition.ConditionValue = ruleConditionCopy.ConditionValue;
        ruleCondition.RuleId = ruleConditionCopy.RuleId;
        ruleCondition.insert();
    }

    GUPPricingRuleExclusionCopy ruleExclusionCopy;
    while select ruleExclusionCopy
            where ruleExclusionCopy.RuleId == this.RuleId
    {
        pricingRule.exclude(ruleExclusionCopy.Exclusion);
    }

    this.clearRuleConditions();
    this.delete();

    ttscommit;
}

public static GUPPricingRuleCopy findByRuleId(RefRecId _ruleId, boolean _selectForUpdate = false)
{
    GUPPricingRuleCopy pricingRuleCopy;

    select firstonly pricingRuleCopy where pricingRuleCopy.RuleId == _ruleId;
    pricingRuleCopy.selectForUpdate(_selectForUpdate);

    return pricingRuleCopy;
}

/// <summary>
/// Clears all child rule conditions and exclusions.
/// </summary>
public void clearRuleConditions()
{
    if (this.RuleId)
    {
        GUPPricingRuleConditionCopy ruleConditionCopy;
        GUPPricingRuleExclusionCopy ruleExclusionCopy;
        ttsbegin;

        delete_from ruleConditionCopy where ruleConditionCopy.RuleId == this.RuleId;
        delete_from ruleExclusionCopy where ruleExclusionCopy.RuleId == this.RuleId;

        ttscommit;
    }
}

/// <summary>
/// Clears all child rule exclusions.
/// </summary>
public void clearRuleExclusions()
{
    if (this.RuleId)
    {
        GUPPricingRuleExclusionCopy ruleExclusionCopy;

        delete_from ruleExclusionCopy where ruleExclusionCopy.RuleId == this.RuleId;
    }
}

/// <summary>
/// Sets pricing group to empty and clear related conditions
/// </summary>
public void clearPricingGroup()
{
    ttsbegin;

    this.selectForUpdate(true);

    this.PriceAttributeGroupName = '';
    this.update();

    this.clearRuleConditions();
    ttscommit;
}

/// <summary>
/// Excludes a customer account or an item id.
/// </summary>
/// <param name = "_exclusion">Exclusion value.</param>
public void addToExclusion(str _exclusion)
{
    if (!this.RecId)
    {
        throw error("@GlobalUnifiedPricing:GUPPricingRule_InsertFirst");
    }

    GUPPricingRuleExclusionCopy ruleExclusionCopy;

    if (!this.isExcluded(_exclusion))
    {
        ruleExclusionCopy.RuleId = this.RuleId;
        ruleExclusionCopy.Exclusion = _exclusion;
        ruleExclusionCopy.insert();
    }
}

/// <summary>
/// Includes a customer account or an item id.
/// </summary>
/// <param name = "_exclusion">Inclusion value.</param>
public void removeFromExclusion(str _exclusion)
{
    if (!this.RecId)
    {
        throw error("@GlobalUnifiedPricing:GUPPricingRule_InsertFirst");
    }

    GUPPricingRuleExclusionCopy ruleExclusionCopy;

    select firstonly ruleExclusionCopy where ruleExclusionCopy.RuleId == this.RuleId && ruleExclusionCopy.Exclusion == _exclusion;

    if (ruleExclusionCopy)
    {
        ruleExclusionCopy.selectForUpdate(true);
        ruleExclusionCopy.delete();
    }
}

public boolean isExcluded(str _exclusion)
{
    GUPPricingRuleExclusionCopy ruleExclusionCopy;

    select firstonly RecId from ruleExclusionCopy where ruleExclusionCopy.RuleId == this.RuleId && ruleExclusionCopy.Exclusion == _exclusion;

    return ruleExclusionCopy.RecId;
}

public void updateAllowMultiValue(boolean _allowMultiValue = false)
{
    ttsbegin;

    this.selectForUpdate(true);
    this.AllowMultiValue = _allowMultiValue;
    this.update();

    ttscommit;
}
